import java.util.*;

class Solution {
    public boolean backspaceCompare(String s, String t) {
        int i = s.length() - 1, j = t.length() - 1;
        while (true) {
            i = nextLetter(s, i);
            j = nextLetter(t, j);
            if (i < 0 || j < 0) return i < 0 && j < 0;   // both must end together
            if (s.charAt(i) != t.charAt(j)) return false;
            i--;
            j--;
        }
    }

    // index of the next letter (moving left from i) that is not erased, or -1
    private int nextLetter(String str, int i) {
        int skip = 0;
        while (i >= 0) {
            if (str.charAt(i) == '#') { skip++; i--; }  // one more erase pending
            else if (skip > 0) { skip--; i--; }         // this letter is erased
            else break;                                 // survivor found
        }
        return i;
    }
}

