function backspaceCompare(s, t) {
  let i = s.length - 1, j = t.length - 1;
  const step = (x, k) => { let skip = 0; while (k >= 0) { if (x[k] === "#") { skip++; k--; } else if (skip) { skip--; k--; } else break; } return k; };
  while (true) {
    i = step(s, i); j = step(t, j);
    if (i < 0 || j < 0) return i < 0 && j < 0;
    if (s[i] !== t[j]) return false;
    i--; j--;
  }
}
